-- 생필품 가격 리포트: 가격 데이터 (export_db_sql.py 로 자동 생성한 파일, 직접 고치지 않는다)
SET client_encoding = 'UTF8';

CREATE TABLE IF NOT EXISTS products (
	id SERIAL NOT NULL, 
	product_name VARCHAR(200) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS ix_products_id ON products (id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_products_product_name ON products (product_name);


SELECT setval(pg_get_serial_sequence('products', 'id'), COALESCE((SELECT MAX(id) FROM products), 1));

CREATE TABLE IF NOT EXISTS price_history (
	id SERIAL NOT NULL, 
	product_id INTEGER NOT NULL, 
	survey_date DATE NOT NULL, 
	avg_price FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_product_date UNIQUE (product_id, survey_date), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);
CREATE INDEX IF NOT EXISTS ix_price_history_survey_date ON price_history (survey_date);
CREATE INDEX IF NOT EXISTS ix_price_history_id ON price_history (id);


SELECT setval(pg_get_serial_sequence('price_history', 'id'), COALESCE((SELECT MAX(id) FROM price_history), 1));

CREATE TABLE IF NOT EXISTS price_changes (
	id SERIAL NOT NULL, 
	product_id INTEGER NOT NULL, 
	survey_date DATE NOT NULL, 
	avg_price FLOAT NOT NULL, 
	prev_price FLOAT, 
	price_diff FLOAT, 
	change_rate FLOAT, 
	yoy_price FLOAT, 
	yoy_diff FLOAT, 
	yoy_change_rate FLOAT, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_change_product_date UNIQUE (product_id, survey_date), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);
CREATE INDEX IF NOT EXISTS ix_price_changes_id ON price_changes (id);
CREATE INDEX IF NOT EXISTS ix_price_changes_survey_date ON price_changes (survey_date);


SELECT setval(pg_get_serial_sequence('price_changes', 'id'), COALESCE((SELECT MAX(id) FROM price_changes), 1));

CREATE TABLE IF NOT EXISTS predictions (
	id SERIAL NOT NULL, 
	product_id INTEGER NOT NULL, 
	base_price FLOAT NOT NULL, 
	predicted_price FLOAT NOT NULL, 
	expected_change_rate FLOAT NOT NULL, 
	raw_expected_change_rate FLOAT NOT NULL, 
	predicted_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id), 
	UNIQUE (product_id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);
CREATE INDEX IF NOT EXISTS ix_predictions_id ON predictions (id);


SELECT setval(pg_get_serial_sequence('predictions', 'id'), COALESCE((SELECT MAX(id) FROM predictions), 1));

